PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name VARCHAR(50) NOT NULL CHECK(length(name)<=50),role VARCHAR(20) NOT NULL DEFAULT 'MEMBER' CHECK(role IN ('ADMIN','MEMBER')),is_active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inquiries(id INTEGER PRIMARY KEY AUTOINCREMENT,title VARCHAR(100) NOT NULL CHECK(length(title)<=100),body TEXT NOT NULL,requester_name VARCHAR(50) NOT NULL CHECK(length(requester_name)<=50),status VARCHAR(20) NOT NULL DEFAULT 'NEW' CHECK(status IN ('NEW','IN_PROGRESS','PENDING','DONE')),assignee_id BIGINT REFERENCES users(id),priority VARCHAR(10) NOT NULL DEFAULT 'MIDDLE' CHECK(priority IN ('HIGH','MIDDLE','LOW')),created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,closed_at DATETIME);
CREATE TABLE IF NOT EXISTS inquiry_histories(id INTEGER PRIMARY KEY AUTOINCREMENT,inquiry_id BIGINT NOT NULL REFERENCES inquiries(id),changed_by BIGINT NOT NULL REFERENCES users(id),field_name VARCHAR(20) NOT NULL CHECK(field_name IN ('status','assignee')),old_value VARCHAR(50),new_value VARCHAR(50),changed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_histories_inquiry_time ON inquiry_histories(inquiry_id,changed_at DESC,id DESC);
